const ExcelJS = require('exceljs');

async function createExcel() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Sheet1');

  // Define column headers
  sheet.columns = [
    { header: 'ID', key: 'id', width: 10 },
    { header: 'Name', key: 'name', width: 25 },
    { header: 'Value', key: 'value', width: 15 },
  ];

  // Style the header row
  sheet.getRow(1).font = { bold: true };

  // Add a sample row (replace with your own data)
  sheet.addRow({ id: 1, name: 'Sample Item', value: 100 });

  // Save the file
  await workbook.xlsx.writeFile('/workspace/data.xlsx');
  console.log('✅ Excel file created: /workspace/data.xlsx');
}

createExcel().catch(console.error);

