const ExcelJS = require('exceljs');

async function addRow() {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile('data.xlsx');
  const sheet = workbook.getWorksheet('Sheet1');

  // Add row by positional values: [ID, Name, Value]
  sheet.addRow([2, 'alice', 42]);

  await workbook.xlsx.writeFile('data.xlsx');
  console.log('✅ Row added successfully!');

  // Re-read to verify
  const wb2 = new ExcelJS.Workbook();
  await wb2.xlsx.readFile('data.xlsx');
  const s2 = wb2.getWorksheet('Sheet1');
  s2.eachRow((row, rowNum) => {
    console.log('Row ' + rowNum + ':', row.values.slice(1).join(' | '));
  });
}

addRow().catch(console.error);
